-- Seeds the admin review queue with the readings withheld from the
-- published dictionary. Generated by scripts/withhold-uncertain.py —
-- edit that, not this.
--
-- Apply in the Supabase SQL editor. Safe to run more than once: a word
-- already in the queue is skipped rather than duplicated, so an
-- editor's work in progress is never overwritten.
--
-- These rows are drafts. dictionary_entries only exposes
-- status='published' rows to the public, so nothing here is reachable
-- from the site until an editor has confirmed the reading and
-- published it — at which point it rejoins the dictionary through the
-- editable layer the page already merges in.

insert into public.dictionary_entries
  (tina, pos, en, fil, layer, status, internal_notes)
